.form-success.visible { display: block; }
.form-success h3 { color: #1B7F37; margin-bottom: 8px; }
.form-success p { font-size: 0.9375rem; color: var(--text); }

.contact-info-cards { display: flex; flex-direction: column; gap: 24px; }

.contact-info-card {
