  flex-shrink: 0;
}
.contact-info-card .info-icon svg { width: 24px; height: 24px; color: var(--primary); }
.contact-info-card h4 { margin-bottom: 4px; }
.contact-info-card p { font-size: 0.9375rem; color: var(--text); }
.contact-info-card a { color: var(--primary); font-weight: 500; }
.contact-info-card a:hover { text-decoration: underline; }

.offices-grid {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 24px;
  margin-top: 48px;
}

.office-card {
  background: var(--bg);
  border-radius: var(--radius-md);
