  .pricing-grid { grid-template-columns: 1fr; max-width: 440px; margin-left: auto; margin-right: auto; }
  .integrations-grid { grid-template-columns: repeat(2, 1fr); }
  .team-grid { grid-template-columns: repeat(2, 1fr); }
}

@media (max-width: 768px) {
  .nav-links, .header-cta { display: none; }
  .hamburger { display: flex; }

  .hero { padding: 120px 0 60px; }
  .hero-home { padding: 120px 0 72px; }
  .page-hero { padding: 110px 0 48px; }
  .section { padding: 64px 0; }

  .features-grid { grid-template-columns: 1fr; }
  .steps-grid { grid-template-columns: 1fr; max-width: 400px; margin-left: auto; margin-right: auto; }
  .stats-grid { grid-template-columns: repeat(2, 1fr); gap: 32px; }
  .pricing-teaser-grid { grid-template-columns: 1fr; max-width: 380px; margin-left: auto; margin-right: auto; }

  .footer-grid { grid-template-columns: repeat(2, 1fr); gap: 32px; }
