[metadata] {"type": "create", "filePath": "/app/output/styles.css", "content": "/* ===== ShiftWise — Global Styles ===== */
@import url('https://fonts.googleapis.com/css2?family=Inter:wght@400;500;600;700;800;900&display=swap');

*, *::before, *::after { margin: 0; padding: 0; box-sizing: border-box; }

:root {
  --primary: #0051C3;
  --primary-dark: #003D94;
  --primary-light: #E8F0FE;
  --accent: #DE5052;
  --accent-dark: #C13E40;
  --dark: #1A1A2E;
  --text: #4A4A68;
  --text-light: #7A7A96;
  --bg: #F7F8FC;
  --white: #FFFFFF;
  --border: #E2E4ED;
  --shadow-sm: 0 1px 3px rgba(26,26,46,0.06);
  --shadow-md: 0 4px 16px rgba(26,26,46,0.08);
  --shadow-lg: 0 8px 32px rgba(26,26,46,0.12);
  --shadow-xl: 0 16px 48px rgba(26,26,46,0.16);
  --radius-sm: 8px;
  --radius-md: 12px;
  --radius-lg: 16px;
  --radius-xl: 24px;
  --transition: 0.3s cubic-bezier(0.4, 0, 0.2, 1);
  --max-width: 1200px;
}

html { scroll-behavior: smooth; font-size: 16px; }

body {
  font-family: 'Inter', -apple-system, BlinkMacSystemFont, 'Segoe UI', sans-serif;
  color: var(--text);
  background: var(--white);
  line-height: 1.6;
  -webkit-font-smoothing: antialiased;
}

a { text-decoration: none; color: inherit; transition: color var(--transition); }
img { max-width: 100%; display: block; }
ul, ol { list-style: none; }
button { font-family: inherit; cursor: pointer; border: none; background: none; }

.container { max-width: var(--max-width); margin: 0 auto; padding: 0 24px; }

/* ===== Typography ===== */
h1, h2, h3, h4, h5, h6 { color: var(--dark); font-weight: 700; line-height: 1.2; }
h1 { font-size: clamp(2.25rem, 5vw, 3.5rem); font-weight: 800; letter-spacing: -0.02em; }
h2 { font-size: clamp(1.75rem, 3.5vw, 2.5rem); font-weight: 800; letter-spacing: -0.01em; }
h3 { font-size: clamp(1.25rem, 2vw, 1.5rem); font-weight: 700; }
h4 { font-size: 1.125rem; font-weight: 600; }

.section-label {
  display: inline-block;
  font-size: 0.8125rem;
  font-weight: 700;
  text-transform: uppercase;
  letter-spacing: 0.08em;
  color: var(--primary);
  margin-bottom: 12px;
}

.section-subtitle {
  font-size: clamp(1.0625rem, 2vw, 1.1875rem);
  color: var(--text);
  max-width: 640px;
  line-height: 1.7;
}

.text-center { text-align: center; }
.text-center .section-subtitle { margin-left: auto; margin-right: auto; }

/* ===== Buttons ===== */
.btn {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 8px;
  padding: 14px 28px;
  font-size: 0.9375rem;
  font-weight: 600;
  border-radius: var(--radius-sm);
  transition: all var(--transition);
  white-space: nowrap;
}

.btn-primary {
  background: var(--primary);
  color: var(--white);
  box-shadow: 0 2px 8px rgba(0,81,195,0.3);
}
.btn-primary:hover {
  background: var(--primary-dark);
  box-shadow: 0 4px 16px rgba(0,81,195,0.4);
  transform: translateY(-1px);
}

.btn-accent {
  background: var(--accent);
  color: var(--white);
  box-shadow: 0 2px 8px rgba(222,80,82,0.3);
}
.btn-accent:hover {
  background: var(--accent-dark);
  box-shadow: 0 4px 16px rgba(222,80,82,0.4);
  transform: translateY(-1px);
}

.btn-outline {
  background: transparent;
  color: var(--primary);
  border: 2px solid var(--primary);
}
.btn-outline:hover {
  background: var(--primary);
  color: var(--white);
}

.btn-white {
  background: var(--white);
  color: var(--primary);
  box-shadow: var(--shadow-md);
}
.btn-white:hover {
  box-shadow: var(--shadow-lg);
  transform: translateY(-1px);
}

.btn-lg { padding: 16px 36px; font-size: 1.0625rem; border-radius: var(--radius-md); }
.btn-sm { padding: 10px 20px; font-size: 0.875rem; }

.btn-group { display: flex; gap: 16px; flex-wrap: wrap; }

/* ===== Header ===== */
.header {
  position: fixed;
  top: 0;
  left: 0;
  right: 0;
  z-index: 1000;
  background: rgba(255,255,255,0.95);
  backdrop-filter: blur(12px);
  border-bottom: 1px solid var(--border);
  transition: box-shadow var(--transition);
}
.header.scrolled { box-shadow: var(--shadow-md); }

.header-inner {
  display: flex;
  align-items: center;
  justify-content: space-between;
  height: 72px;
}

.logo {
  display: flex;
  align-items: center;
  gap: 10px;
  font-size: 1.375rem;
  font-weight: 800;
  color: var(--dark);
  letter-spacing: -0.02em;
}

.logo-icon {
  width: 36px;
  height: 36px;
  background: var(--primary);
  border-radius: var(--radius-sm);
  display: flex;
  align-items: center;
  justify-content: center;
}

.logo-icon svg { width: 22px; height: 22px; }

.nav-links { display: flex; align-items: center; gap: 32px; }
.nav-links a {
  font-size: 0.9375rem;
  font-weight: 500;
  color: var(--text);
  position: relative;
}
.nav-links a:hover,
.nav-links a.active { color: var(--primary); }
.nav-links a::after {
  content: '';
  position: absolute;
  bottom: -4px;
  left: 0;
  width: 0;
  height: 2px;
  background: var(--primary);
  transition: width var(--transition);
}
.nav-links a:hover::after,
.nav-links a.active::after { width: 100%; }

.header-cta { display: flex; align-items: center; gap: 12px; }

.hamburger {
  display: none;
  flex-direction: column;
  gap: 5px;
  width: 28px;
  padding: 4px 0;
  z-index: 1001;
}
.hamburger span {
  display: block;
  width: 100%;
  height: 2.5px;
  background: var(--dark);
  border-radius: 2px;
  transition: all var(--transition);
}
.hamburger.active span:nth-child(1) { transform: rotate(45deg) translate(5px, 5px); }
.hamburger.active span:nth-child(2) { opacity: 0; }
.hamburger.active span:nth-child(3) { transform: rotate(-45deg) translate(5px, -5px); }

.mobile-nav {
  position: fixed;
  top: 0;
  right: -100%;
  width: 300px;
  height: 100vh;
  background: var(--white);
  box-shadow: var(--shadow-xl);
  padding: 88px 32px 32px;
  transition: right var(--transition);
  z-index: 999;
}
.mobile-nav.open { right: 0; }
.mobile-nav a {
  display: block;
  padding: 16px 0;
  font-size: 1.0625rem;
  font-weight: 500;
  color: var(--dark);
  border-bottom: 1px solid var(--border);
}
.mobile-nav a:hover { color: var(--primary); }
.mobile-nav .btn { width: 100%; margin-top: 24px; }

.mobile-overlay {
  position: fixed;
  inset: 0;
  background: rgba(26,26,46,0.5);
  opacity: 0;
  visibility: hidden;
  transition: all var(--transition);
  z-index: 998;
}
.mobile-overlay.visible { opacity: 1; visibility: visible; }

/* ===== Hero Sections ===== */
.hero {
  padding: 140px 0 80px;
  background: linear-gradient(135deg, var(--primary-light) 0%, var(--white) 50%, #FFF0F0 100%);
  position: relative;
  overflow: hidden;
}

.hero::before {
  content: '';
  position: absolute;
  top: -200px;
  right: -200px;
  width: 600px;
  height: 600px;
  background: radial-gradient(circle, rgba(0,81,195,0.06) 0%, transparent 70%);
  border-radius: 50%;
}

.hero::after {
  content: '';
  position: absolute;
  bottom: -150px;
  left: -150px;
  width: 400px;
  height: 400px;
  background: radial-gradient(circle, rgba(222,80,82,0.05) 0%, transparent 70%);
  border-radius: 50%;
}

.hero .container { position: relative; z-index: 1; }

.hero-content { max-width: 720px; }
.hero-content h1 { margin-bottom: 20px; }
.hero-content p {
  font-size: clamp(1.0625rem, 2vw, 1.1875rem);
  color: var(--text);
  margin-bottom: 32px;
  max-width: 580px;
  line-height: 1.7;
}

.hero-home { padding: 140px 0 100px; text-align: center; }
.hero-home .hero-content { max-width: 800px; margin: 0 auto; }
.hero-home .hero-content p { max-width: 640px; margin-left: auto; margin-right: auto; margin-bottom: 36px; }
.hero-home .btn-group { justify-content: center; }

.hero-badge {
  display: inline-flex;
  align-items: center;
  gap: 8px;
  background: var(--white);
  border: 1px solid var(--border);
  padding: 8px 16px;
  border-radius: 100px;
  font-size: 0.8125rem;
  font-weight: 600;
  color: var(--text);
  margin-bottom: 24px;
  box-shadow: var(--shadow-sm);
}

.hero-badge span { color: var(--primary); }

.page-hero {
  padding: 130px 0 60px;
  background: linear-gradient(135deg, var(--primary-light) 0%, var(--white) 100%);
}
.page-hero h1 { margin-bottom: 16px; }

/* ===== Section Spacing ===== */
.section { padding: 96px 0; }
.section-sm { padding: 64px 0; }
.section-alt { background: var(--bg); }

/* ===== Features Section (Home) ===== */
.features-grid {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 32px;
  margin-top: 48px;
}

.feature-card {
  background: var(--white);
  padding: 36px 28px;
  border-radius: var(--radius-lg);
  border: 1px solid var(--border);
  transition: all var(--transition);
}
.feature-card:hover {
  transform: translateY(-4px);
  box-shadow: var(--shadow-lg);
  border-color: transparent;
}

.feature-icon {
  width: 56px;
  height: 56px;
  background: var(--primary-light);
  border-radius: var(--radius-md);
  display: flex;
  align-items: center;
  justify-content: center;
  margin-bottom: 20px;
}
.feature-icon svg { width: 28px; height: 28px; color: var(--primary); }

.feature-card h3 { margin-bottom: 10px; font-size: 1.125rem; }
.feature-card p { font-size: 0.9375rem; line-height: 1.65; color: var(--text-light); }

/* ===== How It Works ===== */
.steps-grid {
  display: grid;
  grid-template-columns: repeat(4, 1fr);
  gap: 32px;
  margin-top: 48px;
}

.step {
  text-align: center;
  position: relative;
}

.step-number {
  width: 48px;
  height: 48px;
  background: var(--primary);
  color: var(--white);
  border-radius: 50%;
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 1.125rem;
  font-weight: 800;
  margin: 0 auto 20px;
}

.step h3 { margin-bottom: 10px; font-size: 1.0625rem; }
.step p { font-size: 0.9375rem; color: var(--text-light); line-height: 1.6; }

.step::after {
  content: '';
  position: absolute;
  top: 24px;
  left: calc(50% + 32px);
  width: calc(100% - 64px);
  height: 2px;
  background: var(--border);
}
.step:last-child::after { display: none; }

/* ===== Stats Banner ===== */
.stats-banner {
  background: var(--dark);
  padding: 72px 0;
}

.stats-grid {
  display: grid;
  grid-template-columns: repeat(4, 1fr);
  gap: 32px;
}

.stat { text-align: center; }
.stat-value {
  font-size: clamp(2rem, 4vw, 3rem);
  font-weight: 900;
  color: var(--white);
  letter-spacing: -0.02em;
  line-height: 1;
}
.stat-value .accent { color: var(--accent); }
.stat-label {
  font-size: 0.9375rem;
  color: rgba(255,255,255,0.65);
  margin-top: 8px;
  font-weight: 500;
}

/* ===== Testimonials Carousel ===== */
.testimonials { overflow: hidden; }

.testimonial-track {
  position: relative;
  max-width: 700px;
  margin: 48px auto 0;
}

.testimonial-slide {
  display: none;
  flex-direction: column;
  align-items: center;
  text-align: center;
  padding: 0 16px;
  animation: fadeSlide 0.5s ease;
}
.testimonial-slide.active { display: flex; }

@keyframes fadeSlide {
  from { opacity: 0; transform: translateX(24px); }
  to { opacity: 1; transform: translateX(0); }
}

.testimonial-quote {
  font-size: clamp(1.0625rem, 2vw, 1.25rem);
  line-height: 1.7;
  color: var(--dark);
  font-style: italic;
  margin-bottom: 28px;
  position: relative;
  padding: 0 20px;
}
.testimonial-quote::before {
  content: '\201C';
  position: absolute;
  top: -16px;
  left: -8px;
  font-size: 4rem;
  color: var(--primary-light);
  font-style: normal;
  line-height: 1;
}

.testimonial-author { font-weight: 700; color: var(--dark); font-size: 0.9375rem; }
.testimonial-role { color: var(--text-light); font-size: 0.875rem; margin-top: 2px; }

.carousel-controls {
  display: flex;
  align-items: center;
  justify-content: center;
  gap: 16px;
  margin-top: 36px;
}

.carousel-btn {
  width: 44px;
  height: 44px;
  border-radius: 50%;
  border: 2px solid var(--border);
  display: flex;
  align-items: center;
  justify-content: center;
  transition: all var(--transition);
  color: var(--text);
}
.carousel-btn:hover {
  border-color: var(--primary);
  color: var(--primary);
  background: var(--primary-light);
}
.carousel-btn svg { width: 18px; height: 18px; }

.carousel-dots {
  display: flex;
  gap: 8px;
}
.carousel-dot {
  width: 10px;
  height: 10px;
  border-radius: 50%;
  background: var(--border);
  transition: all var(--transition);
}
.carousel-dot.active { background: var(--primary); width: 28px; border-radius: 5px; }

/* ===== Pricing Teaser (Home) ===== */
.pricing-teaser-grid {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 24px;
  margin-top: 48px;
}

.pricing-teaser-card {
  background: var(--white);
  border: 1px solid var(--border);
  border-radius: var(--radius-lg);
  padding: 32px 28px;
  text-align: center;
  transition: all var(--transition);
}
.pricing-teaser-card:hover {
  box-shadow: var(--shadow-lg);
  border-color: transparent;
}
.pricing-teaser-card.featured {
  border: 2px solid var(--primary);
  position: relative;
}
.pricing-teaser-card.featured::before {
  content: 'Most Popular';
  position: absolute;
  top: -13px;
  left: 50%;
  transform: translateX(-50%);
  background: var(--primary);
  color: var(--white);
  font-size: 0.75rem;
  font-weight: 700;
  padding: 4px 16px;
  border-radius: 100px;
  text-transform: uppercase;
  letter-spacing: 0.05em;
}

.pricing-teaser-card h3 { font-size: 1.125rem; margin-bottom: 8px; }
.pricing-teaser-price {
  font-size: 2.25rem;
  font-weight: 900;
  color: var(--dark);
  margin-bottom: 4px;
}
.pricing-teaser-price span { font-size: 0.875rem; font-weight: 500; color: var(--text-light); }
.pricing-teaser-desc { font-size: 0.875rem; color: var(--text-light); margin-bottom: 24px; }

/* ===== CTA Section ===== */
.cta-section {
  padding: 96px 0;
  background: linear-gradient(135deg, var(--primary) 0%, var(--primary-dark) 100%);
  text-align: center;
  position: relative;
  overflow: hidden;
}
.cta-section::before {
  content: '';
  position: absolute;
  top: -100px;
  right: -100px;
  width: 400px;
  height: 400px;
  background: rgba(255,255,255,0.05);
  border-radius: 50%;
}
.cta-section::after {
  content: '';
  position: absolute;
  bottom: -80px;
  left: -80px;
  width: 300px;
  height: 300px;
  background: rgba(255,255,255,0.03);
  border-radius: 50%;
}

.cta-section .container { position: relative; z-index: 1; }
.cta-section h2 { color: var(--white); margin-bottom: 16px; }
.cta-section p {
  color: rgba(255,255,255,0.85);
  font-size: 1.125rem;
  margin-bottom: 36px;
  max-width: 560px;
  margin-left: auto;
  margin-right: auto;
}

/* ===== Footer ===== */
.footer {
  background: var(--dark);
  color: rgba(255,255,255,0.65);
  padding: 72px 0 32px;
}

.footer-grid {
  display: grid;
  grid-template-columns: 1.5fr repeat(4, 1fr);
  gap: 40px;
  margin-bottom: 48px;
}

.footer-brand .logo { color: var(--white); margin-bottom: 16px; }
.footer-brand .logo-icon { background: var(--primary); }
.footer-brand p { font-size: 0.875rem; line-height: 1.7; max-width: 260px; }

.footer-col h4 {
  color: var(--white);
  font-size: 0.8125rem;
  font-weight: 700;
  text-transform: uppercase;
  letter-spacing: 0.08em;
  margin-bottom: 20px;
}
.footer-col a {
  display: block;
  padding: 5px 0;
  font-size: 0.875rem;
  transition: color var(--transition);
}
.footer-col a:hover { color: var(--white); }

.footer-bottom {
  border-top: 1px solid rgba(255,255,255,0.1);
  padding-top: 24px;
  display: flex;
  align-items: center;
  justify-content: space-between;
  font-size: 0.8125rem;
}
.footer-bottom-links { display: flex; gap: 24px; }
.footer-bottom-links a:hover { color: var(--white); }

/* ===== Features Page ===== */
.feature-detail {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 64px;
  align-items: center;
}
.feature-detail.reverse { direction: rtl; }
.feature-detail.reverse > * { direction: ltr; }

.feature-detail-content .section-label { margin-bottom: 12px; }
.feature-detail-content h2 { margin-bottom: 16px; }
.feature-detail-content p { margin-bottom: 24px; line-height: 1.7; }

.feature-detail-visual {
  background: var(--bg);
  border-radius: var(--radius-xl);
  padding: 48px;
  display: flex;
  align-items: center;
  justify-content: center;
  min-height: 340px;
  border: 1px solid var(--border);
}

.feature-detail-visual svg { width: 200px; height: 200px; opacity: 0.9; }

.feature-list {
  display: flex;
  flex-direction: column;
  gap: 12px;
  margin-bottom: 28px;
}
.feature-list li {
  display: flex;
  align-items: flex-start;
  gap: 10px;
  font-size: 0.9375rem;
}
.feature-list li svg { flex-shrink: 0; width: 20px; height: 20px; color: var(--primary); margin-top: 2px; }

.integrations-grid {
  display: grid;
  grid-template-columns: repeat(4, 1fr);
  gap: 24px;
  margin-top: 48px;
}

.integration-card {
  background: var(--white);
  border: 1px solid var(--border);
  border-radius: var(--radius-md);
  padding: 28px 24px;
  text-align: center;
  transition: all var(--transition);
}
.integration-card:hover { box-shadow: var(--shadow-md); border-color: transparent; }
.integration-card h3 { font-size: 1rem; margin-bottom: 12px; }
.integration-names { font-size: 0.875rem; color: var(--text-light); line-height: 1.6; }
.integration-icon {
  width: 48px;
  height: 48px;
  background: var(--primary-light);
  border-radius: var(--radius-sm);
  display: flex;
  align-items: center;
  justify-content: center;
  margin: 0 auto 16px;
}
.integration-icon svg { width: 24px; height: 24px; color: var(--primary); }

/* ===== Pricing Page ===== */
.billing-toggle {
  display: flex;
  align-items: center;
  justify-content: center;
  gap: 16px;
  margin-top: 32px;
}

.billing-toggle span { font-size: 0.9375rem; font-weight: 500; color: var(--text-light); }
.billing-toggle span.active { color: var(--dark); font-weight: 600; }

.toggle-switch {
  width: 52px;
  height: 28px;
  background: var(--border);
  border-radius: 14px;
  position: relative;
  cursor: pointer;
  transition: background var(--transition);
}
.toggle-switch.active { background: var(--primary); }
.toggle-switch::after {
  content: '';
  position: absolute;
  top: 3px;
  left: 3px;
  width: 22px;
  height: 22px;
  background: var(--white);
  border-radius: 50%;
  transition: transform var(--transition);
  box-shadow: var(--shadow-sm);
}
.toggle-switch.active::after { transform: translateX(24px); }

.save-badge {
  background: rgba(222,80,82,0.1);
  color: var(--accent);
  font-size: 0.75rem;
  font-weight: 700;
  padding: 4px 10px;
  border-radius: 100px;
}

.pricing-grid {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 24px;
  margin-top: 48px;
}

.pricing-card {
  background: var(--white);
  border: 1px solid var(--border);
  border-radius: var(--radius-lg);
  padding: 40px 32px;
  display: flex;
  flex-direction: column;
  transition: all var(--transition);
}
.pricing-card:hover { box-shadow: var(--shadow-lg); }
.pricing-card.featured {
  border: 2px solid var(--primary);
  position: relative;
  box-shadow: var(--shadow-lg);
}
.pricing-card.featured::before {
  content: 'Most Popular';
  position: absolute;
  top: -13px;
  left: 50%;
  transform: translateX(-50%);
  background: var(--primary);
  color: var(--white);
  font-size: 0.75rem;
  font-weight: 700;
  padding: 4px 16px;
  border-radius: 100px;
  text-transform: uppercase;
  letter-spacing: 0.05em;
}

.pricing-card-header { margin-bottom: 24px; padding-bottom: 24px; border-bottom: 1px solid var(--border); }
.pricing-card-header h3 { font-size: 1.25rem; margin-bottom: 8px; }

.pricing-amount {
  font-size: 3rem;
  font-weight: 900;
  color: var(--dark);
  line-height: 1;
}
.pricing-amount .currency { font-size: 1.5rem; vertical-align: top; font-weight: 700; }
.pricing-amount .period { font-size: 1rem; font-weight: 500; color: var(--text-light); }
.pricing-desc { font-size: 0.875rem; color: var(--text-light); margin-top: 8px; }

.pricing-features { flex: 1; margin-bottom: 28px; }
.pricing-features li {
  display: flex;
  align-items: flex-start;
  gap: 10px;
  padding: 8px 0;
  font-size: 0.9375rem;
}
.pricing-features li svg { flex-shrink: 0; margin-top: 2px; width: 18px; height: 18px; }
.pricing-features li .check { color: var(--primary); }
.pricing-features li .dash { color: var(--border); }

.pricing-card .btn { width: 100%; }

/* ===== FAQ Accordion ===== */
.faq-list { max-width: 740px; margin: 48px auto 0; }

.faq-item {
  border-bottom: 1px solid var(--border);
}

.faq-question {
  display: flex;
  align-items: center;
  justify-content: space-between;
  width: 100%;
  padding: 20px 0;
  font-size: 1rem;
  font-weight: 600;
  color: var(--dark);
  text-align: left;
  transition: color var(--transition);
}
.faq-question:hover { color: var(--primary); }

.faq-icon {
  width: 24px;
  height: 24px;
  flex-shrink: 0;
  transition: transform var(--transition);
}
.faq-item.active .faq-icon { transform: rotate(45deg); }

.faq-answer {
  max-height: 0;
  overflow: hidden;
  transition: max-height 0.4s ease, padding 0.3s ease;
}
.faq-answer-inner {
  padding: 0 0 20px;
  font-size: 0.9375rem;
  line-height: 1.7;
  color: var(--text);
}

/* ===== About Page ===== */
.mission-content {
  max-width: 740px;
  margin: 0 auto;
  text-align: center;
}
.mission-content p {
  font-size: clamp(1.0625rem, 2vw, 1.1875rem);
  line-height: 1.8;
  color: var(--text);
}

.team-grid {
  display: grid;
  grid-template-columns: repeat(4, 1fr);
  gap: 32px;
  margin-top: 48px;
}

.team-card { text-align: center; }
.team-avatar {
  width: 120px;
  height: 120px;
  background: var(--primary-light);
  border-radius: 50%;
  margin: 0 auto 20px;
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 2rem;
  font-weight: 800;
  color: var(--primary);
}
.team-card h3 { font-size: 1.0625rem; margin-bottom: 4px; }
.team-card p { font-size: 0.875rem; color: var(--text-light); }

/* ===== Contact Page ===== */
.contact-layout {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 64px;
  margin-top: 48px;
}

.contact-form { background: var(--white); }

.form-group { margin-bottom: 20px; }
.form-group label {
  display: block;
  font-size: 0.875rem;
  font-weight: 600;
  color: var(--dark);
  margin-bottom: 6px;
}
.form-group label .required { color: var(--accent); }

.form-group input,
.form-group select,
.form-group textarea {
  width: 100%;
  padding: 12px 16px;
  border: 1.5px solid var(--border);
  border-radius: var(--radius-sm);
  font-family: inherit;
  font-size: 0.9375rem;
  color: var(--dark);
  transition: border-color var(--transition), box-shadow var(--transition);
  background: var(--white);
}
.form-group input:focus,
.form-group select:focus,
.form-group textarea:focus {
  outline: none;
  border-color: var(--primary);
  box-shadow: 0 0 0 3px rgba(0,81,195,0.1);
}
.form-group input.error,
.form-group textarea.error {
  border-color: var(--accent);
  box-shadow: 0 0 0 3px rgba(222,80,82,0.1);
}
.form-error {
  font-size: 0.8125rem;
  color: var(--accent);
  margin-top: 4px;
  display: none;
}
.form-error.visible { display: block; }

.form-group textarea { min-height: 120px; resize: vertical; }

.form-success {
  display: none;
  background: #E8F8EE;
  border: 1px solid #34D058;
  border-radius: var(--radius-md);
  padding: 24px;
  text-align: center;
}
.form-success.visible { display: block; }
.form-success h3 { color: #1B7F37; margin-bottom: 8px; }
.form-success p { font-size: 0.9375rem; color: var(--text); }

.contact-info-cards { display: flex; flex-direction: column; gap: 24px; }

.contact-info-card {
  background: var(--bg);
  border-radius: var(--radius-md);
  padding: 28px;
  display: flex;
  align-items: flex-start;
  gap: 16px;
}
.contact-info-card .info-icon {
  width: 48px;
  height: 48px;
  background: var(--primary-light);
  border-radius: var(--radius-sm);
  display: flex;
  align-items: center;
  justify-content: center;
  flex-shrink: 0;
}
.contact-info-card .info-icon svg { width: 24px; height: 24px; color: var(--primary); }
.contact-info-card h4 { margin-bottom: 4px; }
.contact-info-card p { font-size: 0.9375rem; color: var(--text); }
.contact-info-card a { color: var(--primary); font-weight: 500; }
.contact-info-card a:hover { text-decoration: underline; }

.offices-grid {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 24px;
  margin-top: 48px;
}

.office-card {
  background: var(--bg);
  border-radius: var(--radius-md);
  padding: 28px;
  text-align: center;
}
.office-card h3 { font-size: 1.0625rem; margin-bottom: 6px; }
.office-card p { font-size: 0.875rem; color: var(--text-light); }
.office-badge {
  display: inline-block;
  background: var(--primary-light);
  color: var(--primary);
  font-size: 0.75rem;
  font-weight: 700;
  padding: 3px 10px;
  border-radius: 100px;
  margin-top: 8px;
}

/* ===== Responsive ===== */
@media (max-width: 1024px) {
  .features-grid { grid-template-columns: repeat(2, 1fr); }
  .steps-grid { grid-template-columns: repeat(2, 1fr); }
  .step::after { display: none; }
  .stats-grid { grid-template-columns: repeat(2, 1fr); gap: 40px; }
  .footer-grid { grid-template-columns: repeat(3, 1fr); }
  .feature-detail { grid-template-columns: 1fr; gap: 40px; }
  .feature-detail.reverse { direction: ltr; }
  .pricing-grid { grid-template-columns: 1fr; max-width: 440px; margin-left: auto; margin-right: auto; }
  .integrations-grid { grid-template-columns: repeat(2, 1fr); }
  .team-grid { grid-template-columns: repeat(2, 1fr); }
}

@media (max-width: 768px) {
  .nav-links, .header-cta { display: none; }
  .hamburger { display: flex; }

  .hero { padding: 120px 0 60px; }
  .hero-home { padding: 120px 0 72px; }
  .page-hero { padding: 110px 0 48px; }
  .section { padding: 64px 0; }

  .features-grid { grid-template-columns: 1fr; }
  .steps-grid { grid-template-columns: 1fr; max-width: 400px; margin-left: auto; margin-right: auto; }
  .stats-grid { grid-template-columns: repeat(2, 1fr); gap: 32px; }
  .pricing-teaser-grid { grid-template-columns: 1fr; max-width: 380px; margin-left: auto; margin-right: auto; }

  .footer-grid { grid-template-columns: repeat(2, 1fr); gap: 32px; }
  .footer-brand { grid-column: 1 / -1; }
  .footer-bottom { flex-direction: column; gap: 12px; text-align: center; }
  .footer-bottom-links { justify-content: center; }

  .contact-layout { grid-template-columns: 1fr; gap: 40px; }
  .offices-grid { grid-template-columns: 1fr; }
  .team-grid { grid-template-columns: 1fr; max-width: 300px; margin-left: auto; margin-right: auto; }
}

@media (max-width: 480px) {
  .container { padding: 0 16px; }
  .btn-group { flex-direction: column; align-items: stretch; }
  .stats-grid { grid-template-columns: 1fr; }
}
