  text-transform: uppercase;
  letter-spacing: 0.05em;
}

.pricing-teaser-card h3 { font-size: 1.125rem; margin-bottom: 8px; }
.pricing-teaser-price {
  font-size: 2.25rem;
  font-weight: 900;
  color: var(--dark);
  margin-bottom: 4px;
}
.pricing-teaser-price span { font-size: 0.875rem; font-weight: 500; color: var(--text-light); }
.pricing-teaser-desc { font-size: 0.875rem; color: var(--text-light); margin-bottom: 24px; }

/* ===== CTA Section ===== */
.cta-section {
  padding: 96px 0;
